package org.marketreview.nativeapp;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.marketreview.nativeapp.WatchlistWorkspaceModel.*;
public final class WatchlistBackupModel {
 public static final int LIMIT=8*1024*1024;
 static void keys(JSONObject o,String...wanted)throws Exception{Set<String> actual=new HashSet<>();o.keys().forEachRemaining(actual::add);need(actual.equals(new HashSet<>(Arrays.asList(wanted))),"备份含缺失或未知字段，未静默丢弃");}
 static void safeTree(Object v,int depth)throws Exception{need(depth<=64,"备份证据嵌套过深");if(v instanceof String){String s=(String)v;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(Character.isHighSurrogate(c)){need(i+1<s.length()&&Character.isLowSurrogate(s.charAt(i+1)),"备份Unicode无效");i++;}else need(!Character.isLowSurrogate(c),"备份Unicode无效");}need(!java.util.regex.Pattern.compile("(bearer\\s+|[?&](access_token|token|api_key|password|secret)=|://[^/\\s]+:[^/@\\s]+@)",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(s).find(),"来源证据含凭据文本，未导出");}else if(v instanceof JSONArray){JSONArray a=(JSONArray)v;for(int i=0;i<a.length();i++)safeTree(a.get(i),depth+1);}else if(v instanceof JSONObject){JSONObject o=(JSONObject)v;Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next(),compact=k.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");need(!java.util.regex.Pattern.compile("(password|passwd|secret|credential|cookie|authorization|authentication|apikey|accesskey|privatekey|session|token)").matcher(compact).find()&&!Arrays.asList("auth","instruments","items","quote","quotes","day","minute","week","month","year","price","lastprice","bid","ask","volume").contains(compact),"分组证据含行情或凭据字段，未导出/导入");safeTree(k,depth+1);safeTree(o.get(k),depth+1);}}}
 static JSONObject validateConfig(JSONObject c)throws Exception{keys(c,"schema","revision","mainIds","groups");need(text(c,"schema").equals("watchlist-workspace-config/v1"),"备份配置格式不支持");JSONArray roster=new JSONArray(),main=c.getJSONArray("mainIds");for(int i=0;i<main.length();i++)roster.put(object("id",main.get(i),"name",main.get(i)));validate(copy(c).put("schema","watchlist-workspace/v1").put("instruments",roster));JSONArray gs=c.getJSONArray("groups");for(int i=0;i<gs.length();i++){JSONObject g=gs.getJSONObject(i);Iterator<String>it=g.keys();while(it.hasNext())need(Arrays.asList("groupId","name","color","readOnly","memberIds","sourceId","sourceMeta").contains(it.next()),"分组未知字段需先明确备份契约，未丢弃");if(g.getBoolean("readOnly"))need(g.opt("sourceId") instanceof String&&!g.getString("sourceId").trim().isEmpty(),"只读来源组缺少sourceId证据");}safeTree(gs,0);return c;}
 static JSONObject validateBackup(JSONObject e)throws Exception{keys(e,"schema","checksumAlgorithm","sha256","config");need(text(e,"schema").equals("watchlist-workspace-backup/v1")&&text(e,"checksumAlgorithm").equals("watchlist-canonical-sha256/v1")&&e.opt("config") instanceof JSONObject,"备份格式或校验算法不支持");JSONObject c=validateConfig(e.getJSONObject("config"));need(text(e,"sha256").equals(hash(c)),"备份校验不一致，未采用");need(e.toString().getBytes(StandardCharsets.UTF_8).length<=LIMIT,"备份超过8 MiB，未截断");return e;}
 public static JSONObject exportBackup(JSONObject snapshot)throws Exception{JSONObject s=validate(snapshot),c=object("schema","watchlist-workspace-config/v1","revision",s.get("revision"),"mainIds",s.get("mainIds"),"groups",s.get("groups"));validateConfig(c);return copy(validateBackup(object("schema","watchlist-workspace-backup/v1","checksumAlgorithm","watchlist-canonical-sha256/v1","sha256",hash(c),"config",c)));}
 public static byte[] encodeBackup(JSONObject e)throws Exception{return validateBackup(e).toString().getBytes(StandardCharsets.UTF_8);}
 static final class JsonGate {
  final String s;int i=0;JsonGate(String raw){s=raw;}
  void ws(){while(i<s.length()&&" \r\n\t".indexOf(s.charAt(i))>=0)i++;}
  String string()throws Exception{need(i<s.length()&&s.charAt(i)=='"',"备份JSON文本无效");int start=i++;boolean done=false;while(i<s.length()){char c=s.charAt(i++);if(c=='"'){done=true;break;}need(c>=32,"JSON控制字符无效");if(c=='\\'){need(i<s.length(),"JSON转义缺失");char e=s.charAt(i++);if(e=='u'){need(i+4<=s.length(),"JSON Unicode转义缺失");for(int n=0;n<4;n++)need("0123456789abcdefABCDEF".indexOf(s.charAt(i++))>=0,"JSON Unicode转义无效");}else need("\"\\/bfnrt".indexOf(e)>=0,"JSON转义无效");}}need(done,"JSON文本未结束");return new JSONArray("["+s.substring(start,i)+"]").getString(0);}
  void value(int depth)throws Exception{need(depth<=64,"备份JSON嵌套过深");ws();need(i<s.length(),"JSON值缺失");char c=s.charAt(i);if(c=='"'){string();return;}if(c=='{'||c=='['){boolean object=c=='{';Set<String>seen=new HashSet<>();i++;ws();char end=object?'}':']';if(i<s.length()&&s.charAt(i)==end){i++;return;}for(;;){if(object){ws();String k=string();need(seen.add(k),"JSON键重复，未采用");ws();need(i<s.length()&&s.charAt(i++)==':',"JSON冒号缺失");}value(depth+1);ws();need(i<s.length(),"JSON容器未结束");if(s.charAt(i)==end){i++;return;}need(s.charAt(i++)==',',"JSON逗号缺失");}}
   int start=i;while(i<s.length()&&" \r\n\t,]}".indexOf(s.charAt(i))<0)i++;String t=s.substring(start,i);need(t.equals("true")||t.equals("false")||t.equals("null")||t.matches("-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?"),"备份仅接受严格JSON");
  }
  void run()throws Exception{value(0);ws();need(i==s.length(),"JSON尾部含多余内容");}
 }
 public static JSONObject decodeBackup(byte[] bytes)throws Exception{need(bytes!=null&&bytes.length>0&&bytes.length<=LIMIT,"备份为空或超过8 MiB");String raw=new String(bytes,StandardCharsets.UTF_8);need(Arrays.equals(raw.getBytes(StandardCharsets.UTF_8),bytes),"备份UTF-8无效");new JsonGate(raw).run();return copy(validateBackup(new JSONObject(raw)));}
 public static JSONObject previewImport(JSONObject e,JSONObject base,JSONObject current)throws Exception{validateBackup(e);validate(base);validate(current);JSONObject c=e.getJSONObject("config");need(equal(c.get("mainIds"),current.get("mainIds")),"备份主自选身份或顺序不匹配；请先明确协调，未丢成员");JSONObject d=copy(base).put("groups",c.get("groups"));return copy(object("schema","watchlist-backup-import-preview/v1","backup",e,"change",prepare(base,d,current)));}
 public static JSONObject importDraft(JSONObject base,JSONObject p,JSONObject current)throws Exception{keys(p,"schema","backup","change");need(text(p,"schema").equals("watchlist-backup-import-preview/v1")&&p.opt("backup") instanceof JSONObject,"需先预览备份差异");need(equal(p,previewImport(p.getJSONObject("backup"),base,current)),"导入预览或当前配置已变化；未替换草稿");JSONObject d=copy(base).put("groups",p.getJSONObject("change").get("groups"));transition(base,d);return copy(d);}
}
